/**
 * The eval harness. The frozen datasets (tests/fixtures/evals/,
 * generated by tests/eval-datasets.test.ts and never hand-edited) hold the
 * cases; the evaluators here run them through the app's own code paths with
 * the fake models (src/core/harness/testing.ts) in place of a server — a
 * scripted reply, never a live call — and score what actually rode the
 * request and what the person finally sees or hears:
 *
 *  - `evaluateIdentityCase`: the identity block rides every request (before
 *    and after a compaction), and the guarded reply names MKMN AI, never the
 *    scripted wrong name; a voice case scores what `spokenOf` would say.
 *  - `evaluateLongConversationCase`: one scripted conversation (40-120
 *    turns), scored in three modes — the old behaviour (no compaction), the
 *    compaction alone, and the compaction with recall. Overflow is measured
 *    (promptTokens against requestRoom), the fact's ride is checked in the
 *    request, and recall scores the folded turns read back.
 *  - `evaluateKnowledgeCase`: the question against the real fixture index —
 *    hit@4 (the fact among the BM25 top 4, after the one weak-query rewrite
 *    the orchestrator allows), the fact riding the packed sections, the
 *    answer's citations checked by `citeAnswer` against what was loaded, and
 *    an answerer that always over-cites one invented marker, so the count of
 *    invented citations left in the final text is the guard's own score.
 *
 * Records are APPENDED to the results file (one JSON object per line), never
 * rewritten: a run's evidence is append-only, like the evidence registry.
 * Node only (it reads the datasets and appends the records).
 */
import { appendFileSync } from "node:fs";
import type { ChatMessage } from "../../shared/types";
import { promptTokens } from "../context";
import { KEEP_SHARE, compacted, foldedText, planCompaction, recallFolded, requestRoom, wantsCompaction } from "../compaction";
import { citeAnswer, spokenOf } from "../cite";
import { buildSystemPrompt, knowledgeBudget } from "../projects";
import { ASSISTANT_NAME, IDENTITY_INSTRUCTIONS, identityGuardStep } from "./identity";
import { hashText } from "../memo";
import type { KnowledgeIndex } from "../knowledge/store";
import { COVERAGE_MIN, mergeByBestRank, packSections, queryCoverage, type RetrSection } from "../knowledge/retrieve";

// ---------------------------------------------------------------- the datasets

export type EvalKind = "identity" | "longConversation" | "knowledge";
export type LongConvMode = "old" | "compaction" | "compaction+recall";

export interface EvalCase {
  id: string;
  kind: EvalKind;
  lang: "en" | "ar";
  /** The question the person asks (the last user turn). */
  question: string;
  /** The fact that must ride the request (knowledge: the sentence as the file holds it). */
  fact: string;
  /** identity: the wrong name the scripted model says, and the reply it gives. */
  wrongName?: string;
  wrongReply?: string;
  /** identity: score what the voice says (spokenOf). */
  voice?: boolean;
  /** identity: score after the conversation was compacted. */
  afterCompaction?: boolean;
  /** longConversation: the whole scripted conversation, the question last. */
  turns?: { role: "user" | "assistant"; text: string }[];
  /** longConversation: the index in `turns` that carries the fact (early). */
  factTurn?: number;
  /** knowledge: the file (and its place) the fact lives in. */
  file?: string;
  place?: string;
  /** knowledge: the question's language differs from the file's. */
  crossLanguage?: boolean;
  /** knowledge: the search words the weak-query rewrite writes (frozen, in the file's language). */
  searchWords?: string;
}

/** A frozen dataset: the cases and the hash of them (the tests refuse a hand edit). */
export interface EvalDataset {
  id: string;
  description: string;
  hash: string;
  /** knowledge: the recognized words of the scanned fixture, frozen here (the scan's own text layer is empty by design). */
  ocr?: { file: string; pages: string[] }[];
  cases: EvalCase[];
}

/** The fingerprint of a dataset's cases: the generator writes it, the tests verify it. */
export const datasetHashOf = (cases: EvalCase[]): string => hashText(JSON.stringify(cases));

// ---------------------------------------------------------------- the records

export interface CaseResult {
  id: string;
  pass: boolean;
  /** 0/1 flags and scores, named for the report. */
  metrics: Record<string, number>;
  detail?: string;
}

export interface EvalRun {
  dataset: string;
  datasetHash: string;
  mode?: string;
  started: string;
  finished: string;
  results: CaseResult[];
  summary: Record<string, number>;
}

/** One run's record, appended to the results file — append-only, never rewritten. */
export function appendRunRecord(file: string, run: EvalRun): void {
  appendFileSync(file, `${JSON.stringify(run)}\n`, "utf8");
}

/** The run's totals: the case count, the passes, and each metric's mean over the cases that report it. */
export function summarizeRun(results: CaseResult[]): Record<string, number> {
  const summary: Record<string, number> = { cases: results.length, passed: results.filter((r) => r.pass).length };
  const names = [...new Set(results.flatMap((r) => Object.keys(r.metrics)))].sort();
  for (const name of names) {
    const reporting = results.filter((r) => r.metrics[name] !== undefined);
    if (reporting.length) summary[name] = reporting.reduce((n, r) => n + r.metrics[name], 0) / reporting.length;
  }
  return summary;
}

// ---------------------------------------------------------------- the identity eval

/** The system prompt the identity cases ride: the app's own assembly, the identity block first. */
export function identitySystemPrompt(nctx: number): string {
  return buildSystemPrompt({ knowledgeChars: 0, artifacts: false, contextTokens: nctx, conversationTokens: 60 });
}

/**
 * The honest deterministic summarizer the compaction evals use: it stands for
 * a good summary that holds what was discussed but NOT the early facts —
 * exactly the "the summary of it at the start may not hold in full" the
 * recall exists for. A summarizer that echoed the facts would make the
 * compaction mode's factInRequest metric meaningless.
 */
export const honestSummary = async (head: ChatMessage[]): Promise<string> =>
  `Summary of the earlier conversation: ${head.filter((m) => m.role === "user").length} user turns of routine library small talk and notes. No decisions, names or numbers were recorded in it.`;

/** The model seam: the request's messages in, the reply text out — a fake model in place of the server. */
export type EvalServe = (body: { messages: ChatMessage[] }) => string;

export interface IdentityEvalOptions {
  nctx: number;
  maxTokens: number;
  /** The summarizer for the after-compaction cases (default: honestSummary). */
  summarizer?: (head: ChatMessage[]) => Promise<string>;
  /** The model's reply — default: the scripted wrongReply, sent as one answer. */
  serve?: EvalServe;
}

/** The identity block's first line: the marker `withIdentity` keys on, present in every assembled prompt. */
const IDENTITY_MARK = IDENTITY_INSTRUCTIONS.split("\n")[0];

/** Run one identity case: the request as the app builds it, the guard as the app runs it. */
export async function evaluateIdentityCase(c: EvalCase, o: IdentityEvalOptions): Promise<CaseResult> {
  const sys = identitySystemPrompt(o.nctx);
  let messages: ChatMessage[];
  if (c.afterCompaction) {
    // a conversation past the point where it is summarized: the filler rides, the request is folded
    const filler: ChatMessage[] = Array.from({ length: 30 }, (_, i) => ({
      role: i % 2 ? "assistant" : "user",
      content: i % 2
        ? "Noted. Anything else about the schedule?"
        : `Please remind me about the reading room shift on day ${i + 1}, and note that the shelving count is kept in the annex.`,
    }));
    const whole: ChatMessage[] = [{ role: "system", content: sys }, ...filler, { role: "user", content: c.question }];
    const room = requestRoom(o.nctx, o.maxTokens);
    const plan = planCompaction(whole, Math.floor(room * KEEP_SHARE));
    if (!plan) throw new Error(`${c.id}: the after-compaction case built no compaction plan`);
    const summary = await (o.summarizer ?? honestSummary)(plan.head);
    messages = compacted(plan, summary);
  } else {
    messages = [{ role: "system", content: sys }, { role: "user", content: c.question }];
  }

  // the model seam: the scripted wrong reply, served exactly as a fake model serves its request
  const serve: EvalServe = o.serve ?? (() => c.wrongReply ?? "");
  const reply = serve({ messages });

  // the guard, exactly as the harness hook runs it
  const step = identityGuardStep({ status: "ok", reply });
  const final = typeof step.reply === "string" ? step.reply : "";

  const identityRode = String(messages[0]?.content ?? "").includes(IDENTITY_MARK) ? 1 : 0;
  const wrongGone = c.wrongName && c.wrongName !== ASSISTANT_NAME ? (final.includes(c.wrongName) ? 0 : 1) : 1;
  const namesSelf = final.includes(ASSISTANT_NAME) ? 1 : 0;
  const spoken = c.voice ? spokenOf(final) : final;
  const voiceClean = c.voice ? (/\[source \d+\]|^Sources: /m.test(spoken) ? 0 : 1) : 1;
  const metrics: Record<string, number> = { identityRode, wrongGone, namesSelf, ...(c.voice ? { voiceClean } : {}), ...(c.afterCompaction ? { rodeAfterCompaction: identityRode } : {}) };
  const pass = Object.values(metrics).every((n) => n === 1);
  return { id: c.id, pass, metrics, detail: pass ? undefined : `final: ${JSON.stringify(final)}` };
}

// ---------------------------------------------------------------- the long-conversation eval

export interface LongConvEvalOptions {
  nctx: number;
  maxTokens: number;
  /** The summarizer (default: honestSummary — it does not hold the early facts). */
  summarizer?: (head: ChatMessage[]) => Promise<string>;
}

/**
 * Run one long-conversation case in one mode. `pass` means what the mode
 * claims: the old behaviour is the baseline (it OVERFLOWS — that is the
 * failure the fold fixes), the compaction modes must not overflow, and the
 * compaction+recall mode must also carry the early fact back.
 */
export async function evaluateLongConversationCase(c: EvalCase, mode: LongConvMode, o: LongConvEvalOptions): Promise<CaseResult> {
  const room = requestRoom(o.nctx, o.maxTokens);
  const turns = c.turns ?? [];
  const sys: ChatMessage = { role: "system", content: identitySystemPrompt(o.nctx) };
  const conv: ChatMessage[] = turns.map((t) => ({ role: t.role, content: t.text }));
  const draft: ChatMessage = { role: "user", content: c.question };
  const whole = [sys, ...conv, draft];

  const factIn = (ms: ChatMessage[]): number => (ms.some((m) => typeof m.content === "string" && m.content.includes(c.fact)) ? 1 : 0);

  if (mode === "old") {
    // the behaviour without compaction: the whole conversation rides or the request overflows
    const overflow = promptTokens(whole) > room ? 1 : 0;
    const factInRequest = factIn(whole);
    return { id: c.id, pass: overflow === 1, metrics: { overflow, factInRequest }, detail: overflow ? undefined : "the old behaviour did not overflow (the case is too small to be a baseline)" };
  }

  // the compaction modes: fold when the conversation is past COMPACT_AT, answer from the fold
  if (wantsCompaction(whole, o.nctx, o.maxTokens)) {
    const plan = planCompaction(whole, Math.floor(room * KEEP_SHARE));
    if (!plan) return { id: c.id, pass: false, metrics: { overflow: 1 }, detail: "no compaction plan" };
    const summary = await (o.summarizer ?? honestSummary)(plan.head);
    const after = compacted(plan, summary);
    const overflow = promptTokens(after) > room ? 1 : 0;
    let factInRequest = factIn(after);
    let factRecalled = 0;
    if (mode === "compaction+recall") {
      const recalled = recallFolded(foldedText(plan.head), c.question, knowledgeBudget(o.nctx));
      factRecalled = recalled.includes(c.fact) ? 1 : 0;
      factInRequest = Math.max(factInRequest, factRecalled);
    }
    const pass = overflow === 0 && (mode === "compaction+recall" ? factRecalled === 1 : true);
    return { id: c.id, pass, metrics: { overflow, factInRequest, factRecalled } };
  }

  // not past the point where it is summarized: the request rides whole (no overflow, the fact rides)
  const overflow = promptTokens(whole) > room ? 1 : 0;
  return { id: c.id, pass: overflow === 0, metrics: { overflow, factInRequest: factIn(whole), factRecalled: 0 } };
}

// ---------------------------------------------------------------- the knowledge eval

export interface KnowledgeEvalOptions {
  nctx: number;
  /** The packed sections' budget in characters (the app uses the knowledge budget). */
  budgetChars?: number;
}

/**
 * Run one knowledge case against a real index of the fixture corpus. The
 * scripted answerer is an ideal model that quotes the section it read and
 * ALWAYS adds one invented marker ([source 999]) — so the count of invented
 * citations left in the final text scores the guard, never vacuously.
 */
export function evaluateKnowledgeCase(c: EvalCase, index: KnowledgeIndex, o: KnowledgeEvalOptions): CaseResult {
  // the query: the question's own words; when they match nothing (or feebly — a top
  // score under 1, or the top hit sharing too few of the question's own words: a
  // cross-language question, or a match riding one generic word), ONE rewrite with the
  // frozen search words — the words the router or the chat model writes when the
  // orchestrator runs this seam
  let query = c.question;
  let hits = index.search(query, 12);
  // the rewrite earns its chance the way the orchestrator earns it: a
  // cross-language case always, and the weak gate beside it — and the rewrite's
  // hits are searched ALONGSIDE the question's own, merged by best rank, the way
  // the orchestrator merges them
  const weak = !hits.length || hits[0].score < 1 || queryCoverage(c.question, hits[0].text) < COVERAGE_MIN;
  if ((c.crossLanguage || weak) && c.searchWords && c.searchWords !== c.question) {
    query = c.searchWords;
    hits = mergeByBestRank(hits, index.search(query, 12), (h) => h.doc, 12);
  }
  const top4 = hits.slice(0, 4);
  const hitAt4 = top4.some((h) => h.text.includes(c.fact)) ? 1 : 0;

  // the pack: the top 4 (of the 12) packed into the knowledge budget, as the orchestrator does
  const sections: RetrSection[] = index.sections().map((d) => ({ doc: d.doc, fileId: d.fileId, file: d.name, title: d.title, text: d.text, page: d.page, slide: d.slide, sheet: d.sheet, rowFrom: d.rowFrom, rowTo: d.rowTo, scanned: d.scanned }));
  const budget = o.budgetChars ?? knowledgeBudget(o.nctx);
  const packed = packSections(sections, top4.map((h) => h.doc), budget);
  const retrievalRide = packed.body.includes(c.fact) ? 1 : 0;

  // the answerer: quote the fact from the section it read, cite that section, over-cite one invented
  let citedSection = 0;
  for (const m of packed.body.matchAll(/<section source="(\d+)"[^>]*>([\s\S]*?)<\/section>/g)) {
    if (m[2].includes(c.fact)) { citedSection = Number(m[1]); break; }
  }
  const raw = citedSection ? `${c.fact} [source ${citedSection}] [source 999]` : c.fact;

  // the citation check, exactly as the guard hook runs it
  const checked = citeAnswer(raw, packed.loaded);
  const inventedLeft = [...checked.text.matchAll(/\[source (\d+)\]/g)].filter((m) => Number(m[1]) > packed.loaded.length).length;

  const answerAccuracy = checked.text.includes(c.fact) ? 1 : 0;
  const citedCorrectly = citedSection && checked.cited.includes(citedSection) ? 1 : 0;
  const metrics: Record<string, number> = { hitAt4, retrievalRide, answerAccuracy, citedCorrectly, inventedLeft };
  const pass = hitAt4 === 1 && retrievalRide === 1 && answerAccuracy === 1 && citedCorrectly === 1 && inventedLeft === 0;
  return {
    id: c.id,
    pass,
    metrics: { ...metrics, ...(c.crossLanguage ? { crossLanguage: 1 } : {}) },
    detail: pass ? undefined : `query: ${JSON.stringify(query)}; top4: ${top4.map((h) => `${h.name}${h.page ? ` p${h.page}` : ""}`).join(", ")}`,
  };
}
